<?php if($edit||isset($_GET['create'])||$error):?><section class="panel" id="brand-editor"><h2><?=$edit?'Uredi brend':'Novi brend'?></h2><?php startForm('brand',(int)($edit['id']??0));field('name','Naziv brenda',$edit['name']??'');field('slug','Oznaka za brend (mala slova i crtice)',$edit['slug']??'');field('logo_url','Postojeći logo ili HTTPS adresa',$edit['logo_url']??'','text',false);?><label for="brand_logo">Postavi zvanični logo</label><input type="file" id="brand_logo" name="brand_logo" accept="image/png,image/jpeg,image/webp"><p>PNG, JPG ili WebP do 5 MB. Logo se prikazuje proporcionalno, bez rezanja i promjene boja.</p><?php if(!empty($edit['logo_url'])):?><div class="admin-brand-logo <?=!empty($edit['logo_dark'])?'is-dark-logo':''?>"><img src="<?=e(imageSource($edit['logo_url']))?>" alt="<?=e($edit['name'])?>"></div><?php endif;selectField('logo_dark','Podloga logotipa',[0=>'Svijetla',1=>'Tamna (za bijeli logo)'],$edit['logo_dark']??0);field('website','Zvanična web stranica (opcionalno)',$edit['website']??'','url',false);field('sort_order','Redoslijed prikaza',$edit['sort_order']??0,'number');?><label><input type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> Brend je aktivan</label><label><input type="checkbox" name="show_on_home" <?=!$edit||$edit['show_on_home']?'checked':''?>> Prikaži na naslovnici</label><button>Spremi brend</button></form></section><?php endif;?>
<section class="panel"><div class="table-scroll"><table><thead><tr><th>Logo</th><th>Brend</th><th>Artikli</th><th>Prikaz</th><th></th></tr></thead><tbody><?php foreach(query('SELECT b.*,(SELECT COUNT(*) FROM products p WHERE p.brand_id=b.id) product_count FROM brands b ORDER BY b.sort_order,b.name')->fetchAll() as $brand):?><tr><td><div class="admin-brand-logo <?=!empty($brand['logo_dark'])?'is-dark-logo':''?>"><?php if($brand['logo_url']!==''):?><img src="<?=e(imageSource($brand['logo_url']))?>" alt="<?=e($brand['name'])?>"><?php else:?>Bez logotipa<?php endif;?></div></td><td><strong><?=e($brand['name'])?></strong></td><td><a href="?page=products&amp;brand=<?=(int)$brand['id']?>"><?=(int)$brand['product_count']?> artikala</a></td><td><?=$brand['active']?($brand['show_on_home']?'Naslovnica i katalog':'Samo katalog'):'Isključen'?></td><td><a class="btn secondary" href="?page=brands&amp;id=<?=(int)$brand['id']?>#brand-editor">Uredi</a></td></tr><?php endforeach;?></tbody></table></div></section>
